// ---- border intersection so links touch the box edges ----
function border(n,tox,toy){
 const cx=n.x+n.w/2, cy=n.y+n.h/2, dx=tox-cx, dy=toy-cy;
 if(dx===0&&dy===0)return[cx,cy];
 const hw=n.w/2+2, hh=n.h/2+2;
 const sx=dx?hw/Math.abs(dx):1e9, sy=dy?hh/Math.abs(dy):1e9, s=Math.min(sx,sy);
 return [cx+dx*s, cy+dy*s];
}

function edgeVisible(e){ if(e.type==='marriage'||e.type==='romance'||e.type==='divorced'||e.type==='parent'||e.type==='sibling')return show.seed; return true; }
const GRID=20, ALIGN_TH=13; let snap=true;
// align to a tag edge if within ALIGN_TH (priority), otherwise fall back to the grid
function snapAxis(v,edges){let best=null,bd=ALIGN_TH+1;for(const e of edges){const d=Math.abs(e-v);if(d<bd){bd=d;best=e;}}return best!==null?Math.round(best):Math.round(v/GRID)*GRID;}
function snapNode(n){ if(!snap)return;
  const xe=[],ye=[];
  for(const o of nodes){ if(o===n)continue;
    xe.push(o.x, o.x+o.w-n.w, o.x+o.w/2-n.w/2);
    ye.push(o.y, o.y+o.h-n.h, o.y+o.h/2-n.h/2); }
  n.x=snapAxis(n.x,xe); n.y=snapAxis(n.y,ye);
}
function guidesFor(n){ const gx=new Set(),gy=new Set();
  const L=[n.x,n.x+n.w/2,n.x+n.w], T=[n.y,n.y+n.h/2,n.y+n.h];
  for(const o of nodes){ if(o===n)continue;
    [o.x,o.x+o.w/2,o.x+o.w].forEach(v=>L.forEach(l=>{if(Math.abs(v-l)<1)gx.add(v);}));
    [o.y,o.y+o.h/2,o.y+o.h].forEach(v=>T.forEach(t=>{if(Math.abs(v-t)<1)gy.add(v);})); }
  return {gx:[...gx],gy:[...gy]};
}
function drawGuides(g){ lT.innerHTML=''; if(!g||!snap)return;
  (g.gx||[]).forEach(x=>lT.appendChild(el('line',{x1:x,y1:-30000,x2:x,y2:30000,stroke:'#1b6cd6','stroke-width':1.4,'stroke-dasharray':'5 4','vector-effect':'non-scaling-stroke'})));
  (g.gy||[]).forEach(y=>lT.appendChild(el('line',{x1:-30000,y1:y,x2:30000,y2:y,stroke:'#1b6cd6','stroke-width':1.4,'stroke-dasharray':'5 4','vector-effect':'non-scaling-stroke'})));
}
// snap a whole household: grid, or align its box left/right/top/bottom to another household's box
function hhBox(gid,excl){const m=nodes.filter(n=>n.gid===gid);if(!m.length)return null;
  return {minx:Math.min.apply(null,m.map(n=>n.x)),miny:Math.min.apply(null,m.map(n=>n.y)),
          maxx:Math.max.apply(null,m.map(n=>n.x+n.w)),maxy:Math.max.apply(null,m.map(n=>n.y+n.h))};}
function snapHousehold(gid){ if(!snap)return null;
  const b=hhBox(gid); if(!b)return null;
  const others=[...new Set(nodes.filter(n=>n.gid!==gid).map(n=>n.gid))].map(g=>hhBox(g)).filter(Boolean);
  const TH=16;
  let ox=null,bd=TH+1; others.forEach(o=>{[o.minx-b.minx,o.maxx-b.maxx].forEach(off=>{if(Math.abs(off)<bd){bd=Math.abs(off);ox=off;}});});
  if(ox===null)ox=Math.round(b.minx/GRID)*GRID-b.minx;
  let oy=null;bd=TH+1; others.forEach(o=>{[o.miny-b.miny,o.maxy-b.maxy].forEach(off=>{if(Math.abs(off)<bd){bd=Math.abs(off);oy=off;}});});
  if(oy===null)oy=Math.round(b.miny/GRID)*GRID-b.miny;
  nodes.forEach(n=>{if(n.gid===gid){n.x=Math.round(n.x+ox);n.y=Math.round(n.y+oy);}});
  const gx=[],gy=[]; const nb={minx:b.minx+ox,maxx:b.maxx+ox,miny:b.miny+oy,maxy:b.maxy+oy};
  others.forEach(o=>{if(Math.abs(o.minx-nb.minx)<1)gx.push(o.minx);if(Math.abs(o.maxx-nb.maxx)<1)gx.push(o.maxx);
    if(Math.abs(o.miny-nb.miny)<1)gy.push(o.miny);if(Math.abs(o.maxy-nb.maxy)<1)gy.push(o.maxy);});
  return {gx,gy};
}

function poly(g,pts,color,w,dash){const pl=el('polyline',{points:pts,fill:'none',stroke:color,'stroke-width':w,'stroke-linejoin':'round','stroke-linecap':'round'});if(dash)pl.setAttribute('stroke-dasharray',dash);g.appendChild(pl);return pl;}
