  if(c.y > p.y+p.h+8){ const my=(p.y+p.h+c.y)/2; return `${pcx},${p.y+p.h} ${pcx},${my} ${ccx},${my} ${ccx},${c.y}`; }
  const goR=ccx>=pcx; const sx=goR?p.x+p.w:p.x, sy=p.y+p.h/2, ex=goR?c.x:c.x+c.w, ey=c.y+c.h/2, mx=(sx+ex)/2;
  return `${sx},${sy} ${mx},${sy} ${mx},${ey} ${ex},${ey}`;
