 const parentsOf={},pEB={};
 pEdges.forEach(e=>{(parentsOf[e.b]=parentsOf[e.b]||[]);if(!parentsOf[e.b].includes(e.a))parentsOf[e.b].push(e.a);(pEB[e.b]=pEB[e.b]||[]).push(e.id);});
