 '<div class="lg" style="margin-top:6px;align-items:flex-start"><span style="width:12px;height:12px;border-radius:50%;background:#7c3aed;flex:0 0 auto;margin-top:1px"></span><span><b style="color:#7c3aed">violet</b> = links you added/changed<br><span style="color:#8a7f63">(canon links keep their colours)</span></span></div>';

// How-to-use: auto-collapse to an ⓘ after 3s; reopens on tap, stays until X or click-away
const hintEl=document.getElementById('hint'), hintIcon=document.getElementById('hintIcon');
function collapseHint(){hintEl.style.display='none';hintIcon.style.display='flex';}
function openHint(){hintEl.style.display='block';hintIcon.style.display='none';}
let hintTimer=setTimeout(collapseHint,3000);
hintIcon.addEventListener('click',e=>{e.stopPropagation();clearTimeout(hintTimer);openHint();});
document.getElementById('hintClose').addEventListener('click',e=>{e.stopPropagation();collapseHint();});
document.addEventListener('pointerdown',e=>{ if(hintEl.style.display!=='none' && !hintEl.contains(e.target) && e.target!==hintIcon){collapseHint();} },true);

setSceneT();redraw();fit();
